package app.tenshu.ui.legal

import androidx.compose.runtime.Composable

/**
 * `/aboutlibraries.json` on the classpath: every `*-desktop` app's `jvmMain` resources carry it,
 * generated by `exportLibraryDefinitionsJvm` (root `build.gradle.kts`).
 */
@Composable
internal actual fun bundledLicencesReader(): () -> String? = ::readClasspathLicences

internal fun readClasspathLicences(): String? =
    OssComponent::class.java.getResourceAsStream("/$BUNDLED_LICENCES_NAME.json")
        ?.bufferedReader()?.use { it.readText() }
